// The waiting page's words (src/signin-waiting-strings.json): generated by build/waiting-strings.mjs
// from tracy-web's translations (apps/tracy-web/src/lib/i18n), with build/waiting-strings.source.json
// standing in for keys tracy-web does not have yet. Never edited by hand.
import assert from 'node:assert/strict'
import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import test from 'node:test'
import { fileURLToPath } from 'node:url'

const PKG = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const strings = JSON.parse(readFileSync(path.join(PKG, 'src/signin-waiting-strings.json'), 'utf8'))

test('the committed strings are what the generator makes today', () => {
  execFileSync(process.execPath, [path.join(PKG, 'build/waiting-strings.mjs'), '--check'], { stdio: 'pipe' })
})

test('all eight interface languages, each with every key, none empty', () => {
  assert.deepEqual(Object.keys(strings), ['en', 'vi', 'de', 'it', 'fr', 'nl', 'zh', 'es'])
  const keys = Object.keys(strings.en)
  for (const [language, words] of Object.entries(strings)) {
    assert.deepEqual(Object.keys(words), keys, language)
    for (const [key, value] of Object.entries(words)) assert.ok(value.trim() !== '', `${language} ${key}`)
    assert.match(words['desktopWait.bodyEmail'], /\{email\}/, `${language} keeps the {email} slot`)
  }
})
